DWORD GetSyscallNumber(PVOID func_addr) {
    if (!func_addr) return 0;
    BYTE* addr = (BYTE*)func_addr;
    for (int i = 0; i < 32; i++) {
        if (addr[i] == 0xB8) {
            return *(DWORD*)(addr + i + 1) & 0xFFFF;
        }
        if (addr[i] == 0xC3) break;
    }
    return 0;
}

