        fflush(stdout);
        return (char*)buf;
    } else {
        printf("[-] base64_decode: CryptStringToBinaryA (2nd) failed, Error: %lu\n", GetLastError());
        fflush(stdout);
        free(buf);
        return NULL;
    }
}

