    size_t len_str = strlen(str);
    size_t len_pat = strlen(pattern);

    if (len_pat == 0) return (char*)str;
    if (len_pat > len_str) return NULL;

    for (size_t i = 0; i <= len_str - len_pat; i++) {
        if (_strnicmp(str + i, pattern, len_pat) == 0) {
            return (char*)(str + i);
        }
    }
    return NULL;
}

